fn shell_game(n: i32, x: i8) -> i8 {
    // Ensure the initial position is valid
    assert!(x >= 0 && x <= 2);
    
    // Calculate the final position after n moves
    let mut position = x;

    for i in 1..=n {
        if i % 2 == 1 { // Odd move
            position = match position {
                0 => 1,
                1 => 0,
                2 => 2,
                _ => position, // This case should never happen due to the assert
            };
        } else { // Even move
            position = match position {
                1 => 2,
                2 => 1,
                0 => 0,
                _ => position, // This case should never happen due to the assert
            };
        }
    }

    position
}